/* Design system values, from DESIGN.md's frontmatter, which the program
   reads as its design block: the roles #Design publishes and the palette
   the app authors, each colour carrying both appearances. A screen that
   redeclares one of these has forked the system — the shared layer is the
   only declaration. */
:root {
  --primary: light-dark(#111111, #f5f5f5);
  --secondary: light-dark(#555555, #aaaaaa);
  --accent: light-dark(#0055aa, #66aaff);
  --danger: light-dark(#aa0000, #ff6666);
  --neutral: light-dark(#fafafa, #111111);
  --surface: light-dark(#ffffff, #1a1a1a);
  --border: light-dark(#dddddd, #333333);
  --surface-muted: light-dark(#efefef, #242424);
  --shadow-ink-3: light-dark(hsl(220 3% 15% / 3%), hsl(220 40% 2% / 27%));
  --shadow-ink-4: light-dark(hsl(220 3% 15% / 4%), hsl(220 40% 2% / 28%));
  --shadow-ink-5: light-dark(hsl(220 3% 15% / 5%), hsl(220 40% 2% / 29%));
  --shadow-ink-6: light-dark(hsl(220 3% 15% / 6%), hsl(220 40% 2% / 30%));
  --shadow-ink-7: light-dark(hsl(220 3% 15% / 7%), hsl(220 40% 2% / 31%));
  --shadow-ink-8: light-dark(hsl(220 3% 15% / 8%), hsl(220 40% 2% / 32%));
  --shadow-ink-10: light-dark(hsl(220 3% 15% / 10%), hsl(220 40% 2% / 34%));
  --r-sm: 4px;
  --r-md: 8px;
  --r-full: 999px;
  --sp-sm: 8px;
  --sp-md: 16px;
  --sp-lg: 24px;
  --sp-xl: 40px;
  --motion-fast: 110ms;
  --motion-base: 180ms;
  --motion-ease: cubic-bezier(.2, 0, 0, 1);
  --motion-shift: 6px;
  --control-h-xs: 28px;
  --control-h-sm: 32px;
  --control-h: 36px;
  --control-h-lg: 40px;
  --control-pad-x: var(--sp-md);
  --type-display: 2.5rem;
  --type-title: 2rem;
  --type-subtitle: 1.25rem;
  --type-body: 1rem;
  --type-caption: 0.875rem;
  --type-label: 0.75rem;
  --type-leading-title: 1.25;
  --type-leading-body: 1.625;
