  --motion-shift: 6px;
  --control-h-xs: 28px;
  --control-h-sm: 32px;
  --control-h: 36px;
  --control-h-lg: 40px;
  --control-pad-x: var(--sp-md);
  --type-display: 2.5rem;
  --type-title: 2rem;
  --type-subtitle: 1.25rem;
  --type-body: 1rem;
  --type-caption: 0.875rem;
  --type-label: 0.75rem;
  --type-leading-title: 1.25;
