/* Design system values, from DESIGN.md's frontmatter, which the program
   reads as its design block: the roles #Design publishes and the palette
   the app authors, each colour carrying both appearances. A screen that
   redeclares one of these has forked the system — the shared layer is the
   only declaration. */
:root {
  --primary: light-dark(#111111, #f5f5f5);
  --secondary: light-dark(#555555, #aaaaaa);
  --accent: light-dark(#0055aa, #66aaff);
  --danger: light-dark(#aa0000, #ff6666);
  --neutral: light-dark(#fafafa, #111111);
  --surface: light-dark(#ffffff, #1a1a1a);
  --border: light-dark(#dddddd, #333333);
  --surface-muted: light-dark(#efefef, #242424);
  --shadow-ink-3: light-dark(hsl(220 3% 15% / 3%), hsl(220 40% 2% / 27%));
  --shadow-ink-4: light-dark(hsl(220 3% 15% / 4%), hsl(220 40% 2% / 28%));
  --shadow-ink-5: light-dark(hsl(220 3% 15% / 5%), hsl(220 40% 2% / 29%));
  --shadow-ink-6: light-dark(hsl(220 3% 15% / 6%), hsl(220 40% 2% / 30%));
  --shadow-ink-7: light-dark(hsl(220 3% 15% / 7%), hsl(220 40% 2% / 31%));
  --shadow-ink-8: light-dark(hsl(220 3% 15% / 8%), hsl(220 40% 2% / 32%));
  --shadow-ink-10: light-dark(hsl(220 3% 15% / 10%), hsl(220 40% 2% / 34%));
  --r-sm: 4px;
  --r-md: 8px;
  --r-full: 999px;
  --sp-sm: 8px;
  --sp-md: 16px;
  --sp-lg: 24px;
  --sp-xl: 40px;
  --motion-fast: 110ms;
  --motion-base: 180ms;
  --motion-ease: cubic-bezier(.2, 0, 0, 1);
  --motion-shift: 6px;
  --control-h-xs: 28px;
  --control-h-sm: 32px;
  --control-h: 36px;
  --control-h-lg: 40px;
  --control-pad-x: var(--sp-md);
  --type-display: 2.5rem;
  --type-title: 2rem;
  --type-subtitle: 1.25rem;
  --type-body: 1rem;
  --type-caption: 0.875rem;
  --type-label: 0.75rem;
  --type-leading-title: 1.25;
  --type-leading-body: 1.625;
  --shell-bg: var(--primary);
  --shell-fg: var(--surface);
  --shell-rule: var(--border);
  color-scheme: light dark;
}
/* The storybook stamps -dark frames as data-state values. colour-scheme
   is inherited and light-dark() reads it at the point of use, so
   flipping it on the frame resolves every token inside to its twin —
   both appearances reviewable on one device, with no second palette to
   drift from this one. */
.screen[data-state$="-dark"] {
  color-scheme: dark;
}

/* The terminal's chrome, styled here because the terminal ships no
   style: its markup carries stable classes and attributes, and this
   emission — program-owned, design-derived, app-overridable — is the
   only stylesheet they have. Aesthetic values stay behind --shell-*
   variables so an app can retheme without repeating structure. */
/* The scrollbar's room is kept whether or not the page overflows: a
   screen swapping in is as short as its loading state until its data
   lands, and with a classic scrollbar the whole page would jump
   sideways and back on every navigation. */
html { scrollbar-gutter: stable; }
body { margin: 0; font: var(--shell-font, 1rem/1.5 system-ui, sans-serif);
  background: var(--shell-bg); color: var(--shell-fg); }
:where(body > nav a) { color: inherit; text-decoration: none; }
:where(body > nav a:hover) { text-decoration: var(--shell-nav-hover, underline); }
:where(body > nav .shell-nav-icon) { flex: none; width: var(--shell-nav-icon-size, 1.125em); height: var(--shell-nav-icon-size, 1.125em); display: block; }
:where(body > nav > a[data-display="icon-only"]) { min-width: var(--control-h-sm, 32px); min-height: var(--control-h-sm, 32px); }
:where(body > nav > a[data-display="icon-only"] > .shell-nav-label) {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
:where(body > nav .shell-who) { display: flex; align-items: center; gap: 5px; min-width: 0; min-height: 24px; }
:where(body > nav .shell-who .name) { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
:where(body > nav .shell-who .name:empty) { display: none; }
:where(body > nav .shell-who .name:not(:empty))::after { content: " ·"; }
:where(body > nav .shell-who .handle) { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
/* De-emphasis comes from weight alone: layered opacity on --shell-fg
   lands below 4.5:1 contrast on both themes' nav ground. */
/* A short word is still a target: "sair" sets 23px of text, under the
   24px minimum a finger needs, so the box keeps the floor the label
   does not. */
:where(body > nav :is(.shell-signout, .shell-signin, .shell-register, .shell-provider)) { font: inherit; font-weight: 400;
  color: inherit; background: none; border: 0; padding: 0; cursor: pointer;
  flex: none; white-space: nowrap;
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 24px; min-width: 24px; }
/* Dock posture (`shell.nav: "dock"`): centered floating pill capsule anchored
   at the bottom edge across viewports (`env(safe-area-inset-bottom)` aware),
   leaving the top edge completely chrome-free while reserving bottom clearance
   on `#app`. */
:where(body > nav) {
  position: fixed;
  inset-block-end: max(var(--sp-md, 16px), env(safe-area-inset-bottom, 0px));
  inset-inline: 0; z-index: 10;
  width: fit-content; max-width: calc(100% - var(--sp-lg, 24px));
  margin-inline: auto;
  background: var(--shell-nav-bg, var(--shell-bg));
  display: flex; gap: var(--shell-nav-gap, 4px);
  flex-wrap: nowrap; align-items: center;
  min-height: var(--shell-nav-height, 48px); box-sizing: border-box;
  overflow-x: auto; scrollbar-width: none;
  padding: var(--shell-nav-pad, 6px 8px);
  font-size: var(--shell-nav-size, var(--type-caption, 0.875rem));
  font-weight: var(--shell-nav-weight, 500);
  border: 1px solid var(--shell-rule);
  border-radius: var(--shell-nav-radius, var(--r-full, 999px));
  box-shadow: var(--shell-nav-shadow, var(--shadow-3)); }
:where(body > nav)::-webkit-scrollbar { display: none; }
:where(body > nav > .shell-brand) { flex: none; white-space: nowrap;
  font-weight: var(--shell-brand-weight, 700); letter-spacing: -0.015em;
  padding-inline: var(--sp-sm, 10px);
  border-inline-end: 1px solid color-mix(in srgb, currentColor 14%, transparent);
  margin-inline-end: 2px; }
:where(body > nav > a) { white-space: nowrap; flex: none;
  display: inline-flex; align-items: center; gap: var(--sp-sm, 6px);
  min-height: var(--control-h-sm, 36px); box-sizing: border-box;
  padding-block: var(--shell-nav-link-pad-y, 6px); padding-inline: var(--shell-nav-link-pad-x, 14px);
  border-radius: var(--shell-nav-link-radius, var(--r-full, 999px));
  transition: background-color var(--motion-fast, 110ms) var(--motion-ease, ease), color var(--motion-fast, 110ms) var(--motion-ease, ease), box-shadow var(--motion-fast, 110ms) var(--motion-ease, ease); }
:where(body > nav > a:hover) {
  background: var(--shell-nav-hover-bg, color-mix(in srgb, currentColor 7%, transparent));
  text-decoration: var(--shell-nav-hover, none); }
:where(body > nav > a[aria-current="page"]) {
  background: var(--shell-nav-active-bg, color-mix(in srgb, currentColor 10%, transparent));
  color: var(--shell-nav-active-fg, inherit);
  font-weight: var(--shell-nav-active-weight, 600);
  box-shadow: var(--shell-nav-active-shadow, inset 0 0 0 1px color-mix(in srgb, currentColor 18%, transparent)); }
:where(body > nav .shell-me) { flex: none; display: flex; align-items: center; gap: var(--sp-sm, 8px); padding-inline-end: 4px; }
:where(body > nav .shell-who) { max-width: var(--shell-who-max, 24ch); }
:where(body > nav > a ~ .shell-me) {
  padding-inline-start: var(--shell-nav-me-pad, var(--sp-sm, 10px));
  border-inline-start: var(--shell-nav-me-rule, 1px solid color-mix(in srgb, currentColor 16%, transparent)); }
:where(body > nav .shell-me :is(.shell-signout, .shell-signin, .shell-register, .shell-provider)) {
  flex: none; display: inline-flex; align-items: center; justify-content: center;
  min-height: var(--control-h-xs, 28px); box-sizing: border-box;
  padding-block: var(--shell-nav-btn-pad-y, 4px); padding-inline: var(--shell-nav-btn-pad-x, 10px); white-space: nowrap;
  border: var(--shell-nav-btn-border, 1px solid color-mix(in srgb, currentColor 20%, transparent)); border-radius: var(--r-full, 999px);
  font-weight: 500;
  transition: background-color var(--motion-fast, 110ms) var(--motion-ease, ease), border-color var(--motion-fast, 110ms) var(--motion-ease, ease); }
:where(body > nav .shell-me :is(.shell-signout, .shell-signin, .shell-register, .shell-provider):hover) {
  background: var(--shell-nav-hover-bg, color-mix(in srgb, currentColor 7%, transparent));
  text-decoration: none; }
:where(body:has(> nav:not([hidden])) > #app) {
  padding-block-end: calc(var(--shell-nav-clearance, 84px) + env(safe-area-inset-bottom, 0px)); box-sizing: border-box; }
@media print {
  :where(body > nav) { display: none; }
  :where(body:has(> nav:not([hidden])) > #app) { padding-block-end: 0; }
}
:where(body > nav > a[data-display="icon-only"]) { padding-inline: var(--shell-nav-icon-pad-x, 6px); justify-content: center; gap: 0; }
:where(body > nav[hidden]) { display: none; }

/* Not a preference to weigh against the design: durations collapse
   and the interpreter's exit path, which waits on running animations,
   finds none and removes immediately. */
@media (prefers-reduced-motion: reduce) {
  :root { --motion-fast: 0s; --motion-base: 0s; --motion-shift: 0px; }
}

/* Lifecycle slots the interpreter stamps at moments no screen can
   observe. Keyframes, not transitions: screens style rows with
   transition, and the cascade would hand them the whole shorthand.
   These bindings are deliberately rebindable — a screen may point
   them at its own keyframes; the interpreter waits on whatever
   animations actually run. */
@keyframes shell-item-enter {
  from { opacity: 0; transform: translateY(var(--motion-shift)); }
}
@keyframes shell-item-exit {
  to { opacity: 0; transform: scale(.98); }
}
[data-id][data-enter] { animation: shell-item-enter var(--motion-base) var(--motion-ease); }
/* forwards holds the departed row invisible for the frames between
   the animation ending and the interpreter removing the node. */
[data-id][data-exit] { animation: shell-item-exit var(--motion-base) var(--motion-ease) forwards; }
@keyframes shell-reveal {
  from { opacity: 0; transform: translateY(calc(var(--motion-shift) * -1)); }
}
.empty, .invalid, .store-error {
  animation: shell-reveal var(--motion-base) var(--motion-ease);
}
/* A screen arriving on the navigation stack; the one it replaces is
   hidden at once — overlapping two live screens would need a stacking
   layout the terminal does not own. */
.shell-screen { transition: opacity var(--motion-fast) var(--motion-ease); }
.shell-screen[data-entering] { opacity: 0; }

/* The login ceremony — the one full surface the terminal renders,
   on the same tokens as everything else. */
body:has(.shell-login) { background: var(--login-surface, var(--surface)); }
.shell-login {
  box-sizing: border-box; min-height: 100svh; display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(280px, .8fr);
  align-items: center; gap: clamp(48px, 8vw, 128px);
  max-width: 1160px; margin: auto; padding: clamp(32px, 7vw, 96px);
  color: var(--primary, var(--shell-fg));
}
.shell-login .login-intro { padding-block: 32px; }
.shell-login .login-mark {
  display: grid; place-items: center; width: 56px; height: 56px;
  margin-block-end: 48px; color: var(--accent, var(--shell-fg));
  border: 1px solid var(--shell-rule); border-radius: var(--r-md, 8px);
  font: 400 32px/1 var(--shell-heading-font, ui-serif, Georgia, serif);
}
.shell-login h1 {
  margin: 0; font-family: var(--shell-heading-font, ui-serif, Georgia, serif);
  font-size: clamp(48px, 6.5vw, 88px); font-weight: 400; line-height: 1.05;
  letter-spacing: -.055em; overflow-wrap: anywhere;
}
.shell-login .login-hint {
  margin: 28px 0 0; max-width: 32ch; font-size: 1.125rem; line-height: 1.65;
  color: var(--secondary, var(--shell-fg));
}
.shell-login form {
  box-sizing: border-box; width: 100%; margin: 0; padding-block: 40px;
  border-block: 1px solid var(--shell-rule);
}
.shell-login .login-actions { display: grid; gap: 12px; }
.shell-login button, .shell-login .login-provider {
  box-sizing: border-box; display: flex; align-items: center; justify-content: center;
  width: 100%; min-height: 56px; padding: 14px 20px; font: inherit;
  font-size: .9375rem; font-weight: 600; text-align: center; text-decoration: none;
  line-height: 1.5; border: 1px solid var(--shell-rule); border-radius: var(--r-sm, 6px);
  background: var(--surface); color: var(--primary, var(--shell-fg)); cursor: pointer;
  transition: background 150ms ease, border-color 150ms ease, transform 150ms ease;
}
.shell-login .login-provider { background: var(--primary, var(--shell-fg)); color: var(--surface); border-color: transparent; }
.shell-login .login-provider ~ .login-passkey { background: var(--surface); color: var(--primary, var(--shell-fg)); border-color: var(--shell-rule); }
.shell-login .login-passkey { background: var(--primary, var(--shell-fg)); color: var(--surface); border-color: transparent; }
.shell-login .login-guest { margin-block-start: 12px; border-color: transparent; background: transparent; color: var(--secondary, var(--shell-fg)); font-weight: 400; }
.shell-login button:hover, .shell-login .login-provider:hover { transform: translateY(-1px); }
.shell-login .login-provider:hover { filter: brightness(1.15); }
.shell-login .login-guest:hover { color: var(--primary, var(--shell-fg)); background: var(--surface-muted, var(--surface)); }
.shell-login :is(button, a):focus-visible { outline: 3px solid var(--accent, var(--shell-fg)); outline-offset: 4px; }
.shell-login .login-error { color: var(--danger); margin: 0 0 20px; font-size: .9375rem; }
@media (max-width: 700px) {
  .shell-login { grid-template-columns: minmax(0, 1fr); align-content: center; gap: 40px; padding: 48px 28px; }
  .shell-login .login-intro { padding: 0; }
  .shell-login .login-mark { margin-block-end: 32px; }
  .shell-login h1 { font-size: clamp(48px, 13vw, 72px); }
  .shell-login .login-hint { margin-block-start: 20px; font-size: 1rem; }
  .shell-login form { padding-block: 28px; }
}
@media (prefers-reduced-motion: reduce) {
  .shell-login button, .shell-login .login-provider { transition: none; }
  .shell-login button:hover, .shell-login .login-provider:hover { transform: none; }
}
